#ifndef TLNO_CORE_SHELL_CART2SPH_HPP
#define TLNO_CORE_SHELL_CART2SPH_HPP

// Cartesian -> spherical (real solid harmonic) transform for one shell.
//
// The recurrences produce Cartesian integrals; the production NMR/CC pipeline
// consumes spherical-harmonic AOs.  For a shell-pair block the spherical result
// is  M_sph = Csc_a^T M_cart Csc_b,  where Csc maps the (L+1)(L+2)/2 Cartesian
// components of a shell to its 2L+1 spherical components.  Csc is a fixed,
// *sparse* per-L table (8 nnz for d, 16 for f, 28 for g vs 30/70/135 dense),
// generated by gen_cart2sph_tables.py for TLNO's unit-diagonal Cartesian
// normalization and descending-lex Cartesian order. Shared shell utilities
// are available to both one-electron and two-electron integral engines.

namespace tlno::core::shell {

constexpr int kCart2SphMaxL = 4; // s,p,d,f,g

constexpr int cart_count(int L) { return (L + 1) * (L + 2) / 2; }
constexpr int sph_count(int L) { return 2 * L + 1; }

// Transform one Cartesian shell-pair block to spherical, two sparse passes:
//   sph[sa*nsb + sb] = sum_{ca,cb} Csc_a[ca,sa] cart[ca*ldb + cb] Csc_b[cb,sb]
// cart: cart_count(La) x cart_count(Lb), row-major, row stride `ldb` (so a
//       window of a larger block can be passed directly).
// sph:  sph_count(La) x sph_count(Lb), row-major, contiguous.
// scratch: >= cart_count(La) * sph_count(Lb) doubles (caller-owned, reused).
void cart2sph_block(int La, int Lb, const double* cart, int ldb, double* sph, double* scratch);

} // namespace tlno::core::shell

#endif
